const meses = ['Janeiro','Fevereiro','Março','Abril','Maio','Junho','Julho','Agosto','Setembro','Outubro','Novembro','Dezembro'];
const hoje  = new Date();
const mesAtual    = meses[hoje.getMonth()];
const diaAtual    = String(hoje.getDate()).padStart(2,'0');
const mesNum      = String(hoje.getMonth()+1).padStart(2,'0');
const anoAtual    = hoje.getFullYear();
const dataHoje    = `${diaAtual}/${mesNum}/${anoAtual}`;
const diasMes     = new Date(anoAtual, hoje.getMonth()+1, 0).getDate();
const diasRestantes = diasMes - hoje.getDate();
const diaSemana   = ['Domingo','Segunda','Terça','Quarta','Quinta','Sexta','Sábado'][hoje.getDay()];
return [{ json: { mesAtual, dataHoje, diaAtual: parseInt(diaAtual), diasMes, diasRestantes, anoAtual, diaSemana } }];

const lancamentos = $('Ler Lançamentos do Mês').all().map(i=>i.json);
const orcamentos  = $('Ler Orçamentos').all().map(i=>i.json);
const memorias    = $('Ler Memória do Agente').all().map(i=>i.json);
const ctx         = $('Obter Data Atual').first().json;
const { mesAtual, dataHoje, diaAtual, diasMes, diasRestantes, diaSemana } = ctx;

// Limites de orçamento
const limites = {};
let orcamento_total = 0;
orcamentos.forEach(o => {
  const cat = o['Categoria']||'';
  const lim = parseFloat(o['Limite Mensal (R$)']||0);
  if (cat) { limites[cat] = lim; orcamento_total += lim; }
});

// Gastos por categoria, banco e dia
const gastos = {};
const gastos_hoje = {};
const gastos_por_banco = {};
const gastos_por_dia = {};

lancamentos.forEach(l => {
  const tipo  = l['Tipo']||'';
  const cat   = l['Categoria']||'Outros';
  const val   = parseFloat(l['Valor (R$)']||0);
  const data  = l['Data']||'';
  const banco = l['Cartão']||l['cartao']||'Outros';

  if (tipo === 'Despesa') {
    gastos[cat] = (gastos[cat]||0) + val;
    gastos_por_banco[banco] = (gastos_por_banco[banco]||0) + val;
    gastos_por_dia[data] = (gastos_por_dia[data]||0) + val;
    if (data === dataHoje) gastos_hoje[cat] = (gastos_hoje[cat]||0) + val;
  }
});

const total_despesas  = Object.values(gastos).reduce((s,v)=>s+v, 0);
const total_hoje      = Object.values(gastos_hoje).reduce((s,v)=>s+v, 0);
const total_receitas  = lancamentos.filter(l=>l['Tipo']==='Receita').reduce((s,l)=>s+parseFloat(l['Valor (R$)']||0), 0);

// Métricas de projeção
const media_diaria  = diaAtual > 0 ? total_despesas / diaAtual : 0;
const projecao_mes  = media_diaria * diasMes;
const economia_proj = total_receitas - projecao_mes;
const taxa_poupanca = total_receitas > 0 ? ((total_receitas - total_despesas) / total_receitas * 100) : 0;

// Top dias de gasto
const top_dias = Object.entries(gastos_por_dia)
  .sort((a,b) => b[1]-a[1]).slice(0,3)
  .map(([d,v]) => `${d}: R$ ${v.toFixed(2).replace('.',',')}`);

// Top bancos
const top_bancos = Object.entries(gastos_por_banco)
  .sort((a,b) => b[1]-a[1]).slice(0,3)
  .map(([b,v]) => `${b}: R$ ${v.toFixed(2).replace('.',',')}`);

// Status por categoria
const status_cats = Object.entries(gastos).map(([cat, gasto]) => {
  const lim = limites[cat] || 0;
  const restante = lim > 0 ? lim - gasto : null;
  const pct = lim > 0 ? gasto/lim : null;
  const status = pct === null ? 'sem_limite' : pct >= 1.0 ? 'ultrapassado' : pct >= 0.8 ? 'atencao' : 'ok';
  return { cat, gasto, lim, pct, restante, status };
}).sort((a,b) => (b.pct||0) - (a.pct||0));

// Memória recente
const mem_texto = memorias.slice(-15)
  .map(m => `[${m['Data']||''}] ${m['Observação']||m['observacao']||''}`)
  .join('\n') || 'Primeiro relatório do período.';

const pct_mes = Math.round((diaAtual / diasMes) * 100);
const ritmo_str = projecao_mes > orcamento_total
  ? `⚠️ Projeção R$ ${projecao_mes.toFixed(2).replace('.',',')} ACIMA do orçamento R$ ${orcamento_total.toFixed(2).replace('.',',')}`
  : `✅ Projeção R$ ${projecao_mes.toFixed(2).replace('.',',')} dentro do orçamento R$ ${orcamento_total.toFixed(2).replace('.',',')}`;

// ─── CONHECIMENTO DE PLANEJAMENTO FINANCEIRO ─────────────────────────────────
const conhecimento_financeiro = `FRAMEWORK DE ANÁLISE FINANCEIRA – use para embasar os conselhos:

• Regra 50-30-20: 50% necessidades (moradia/alimentação/transporte/saúde) | 30% desejos (lazer/vestuário/assinaturas) | 20% poupança/investimentos
• Taxa de poupança saudável: ≥ 20% da renda
• Sinais de alerta automáticos:
  - Alimentação fora > 15% da renda → sugira cozinhar mais
  - Assinaturas > 5% da renda → sugira auditoria de assinaturas
  - Lazer > 20% → alerta de consumo excessivo
  - Investimentos = zero → emergência, prioridade máxima
  - Saldo negativo → crise financeira, cortes imediatos
• Estratégias por categoria:
  - Alimentação: planejamento semanal, lista de compras, priorize hortifruti
  - Transporte: calcule custo/km Uber vs carro próprio vs transporte público
  - Assinaturas: cancele o que não usou nos últimos 30 dias
  - Lazer: eventos gratuitos, parques, streaming compartilhado
  - Saúde: prevenção é 10x mais barata que tratamento`;

// ─── PROMPT PARA CLAUDE ──────────────────────────────────────────────────────
const contexto = `${conhecimento_financeiro}

---
Você é um consultor financeiro pessoal experiente e empático. Analise os dados abaixo e escreva uma mensagem de WhatsApp que pareça vir de um amigo especialista — direto, humano, útil e específico.

DATA: ${diaSemana}, ${dataHoje} — ${mesAtual} (dia ${diaAtual}/${diasMes} | ${pct_mes}% do mês | ${diasRestantes} dias restantes)

GASTOS DE HOJE (${dataHoje}):
Total: R$ ${total_hoje.toFixed(2).replace('.',',')}
${Object.entries(gastos_hoje).length > 0
  ? Object.entries(gastos_hoje).map(([c,v])=>`• ${c}: R$ ${v.toFixed(2).replace('.',',')}`).join('\n')
  : 'Nenhum gasto registrado hoje.'}

RESUMO DO MÊS:
Receitas: R$ ${total_receitas.toFixed(2).replace('.',',')}
Despesas: R$ ${total_despesas.toFixed(2).replace('.',',')}
Saldo: R$ ${(total_receitas-total_despesas).toFixed(2).replace('.',',')}
Taxa de poupança atual: ${taxa_poupanca.toFixed(1)}%
Média diária de gastos: R$ ${media_diaria.toFixed(2).replace('.',',')}

GASTOS POR CATEGORIA vs ORÇAMENTO:
${status_cats.map(s => {
  const icon = s.status === 'ultrapassado' ? '🔴' : s.status === 'atencao' ? '🟡' : s.pct !== null ? '🟢' : '⚪';
  const pct_str = s.pct !== null
    ? ` (${(s.pct*100).toFixed(0)}% do limite R$ ${s.lim.toFixed(2).replace('.',',')}${s.restante !== null && s.restante > 0 ? ` | sobram R$ ${s.restante.toFixed(2).replace('.',',')}` : s.restante !== null ? ' | ESGOTADO' : ''})`
    : ' (sem limite definido)';
  return `${icon} ${s.cat}: R$ ${s.gasto.toFixed(2).replace('.',',')}${pct_str}`;
}).join('\n')}

GASTOS POR BANCO/CARTÃO:
${top_bancos.join('\n') || 'Nenhum dado.'}

DIAS COM MAIOR GASTO NO MÊS:
${top_dias.join('\n') || 'Nenhum dado.'}

PROJEÇÃO:
${ritmo_str}
Economia projetada ao fim do mês: R$ ${economia_proj.toFixed(2).replace('.',',')}

HISTÓRICO / MEMÓRIA:
${mem_texto}

---
ESCREVA UMA MENSAGEM DE WHATSAPP com *negrito* e emojis. Máximo 400 palavras.
Estrutura:
1. Saudação com dia da semana
2. O que aconteceu hoje (gastos ou ausência)
3. Retrato do mês (onde o dinheiro está indo — use metáfora simples)
4. 1-2 categorias que merecem atenção (baseadas nos dados reais)
5. Projeção: como o mês vai terminar se o ritmo continuar
6. 1 conselho concreto e acionável baseado nos dados (não genérico!)
7. Frase motivacional curta

Use os números reais. Seja específico, não genérico.`;

return [{ json: {
  model: 'claude-opus-4-6',
  max_tokens: 1800,
  messages: [{ role: 'user', content: contexto }],
  _ctx: { mesAtual, dataHoje, total_hoje, total_despesas, total_receitas, media_diaria, projecao_mes, economia_proj, status_cats }
} }];

const msg_claude = $input.first().json.content?.[0]?.text || 'Erro ao gerar análise.';
const ctx = $('Montar Contexto para Agente').first().json._ctx;
return [{ json: { mensagem: msg_claude, ...ctx } }];
